// Counts how often this file was evaluated in the current runtime. Every
// execution starts fresh, so it is 1 on every run.
globalThis.gasbbFileEvaluations = (globalThis.gasbbFileEvaluations || 0) + 1;

function gasbbSelfTest() {
  // Set at the end of every run; still set next time means state carried over
  const leftover = globalThis.gasbbPreviousRun;
  const results = [];
  function check(name, f) {
    const t0 = Date.now();
    try {
      const v = f();
      results.push({ name, ok: true, ms: Date.now() - t0, value: JSON.stringify(v) });
    } catch (e) {
      results.push({ name, ok: false, ms: Date.now() - t0, error: String(e && e.stack || e) });
    }
  }
  function eq(a, b) {
    if (JSON.stringify(a) !== JSON.stringify(b)) throw new Error(JSON.stringify(a) + " != " + JSON.stringify(b));
    return a;
  }
  check("first eval (context init)", () => eq(gasbb.evalString("(+ 1 2)"), 3));
  check("second eval", () => eq(gasbb.evalString("(reduce + (range 1000))"), 499500));
  check("cell", () => eq(gasbb.cell("(* %1 %2)", [6, 7]), 42));
  check("cell spill", () => eq(gasbb.cell("(frequencies (map first %))", [[["a"], ["b"], ["a"]]]), [["a", 2], ["b", 1]]));
  check("cell date", () => eq(gasbb.cell("(.getFullYear %)", [new Date(2026, 0, 1)]), 2026));
  check("load a .clj file via HtmlService + require", () => eq(gasbb.run("test.clj", "test/info"), { "loaded": true, "shout": "HI!" }));
  check("sheets: write + read maps", () => eq(gasbb.run("test.clj", "test/roundtrip"), [{ "name": "Ada", "age": 36 }, { "name": "Cy", "age": 44 }]));
  check("interop with services", () => gasbb.evalString("(str (.getName (.getActiveSpreadsheet js/SpreadsheetApp)))"));
  check("println -> console.log", () => gasbb.evalString('(println "hello from gasbb" (js/Date.))'));
  check("repl replay", () => eq(gasbb.replEval(["(def x 41)"], "(inc x)").value, "42"));
  check("repl ns carries over", () => {
    const r1 = gasbb.replEval([], "(ns foo (:require [clojure.string :as s]))");
    return eq(gasbb.replEval(Array.from(r1.keep), '(s/upper-case "x")').value, '"X"');
  });
  check("cell table from maps", () => eq(gasbb.cell("[{:a 1 :b 2} {:b 3 :a 4}]", []), [["a", "b"], [1, 2], [4, 3]]));
  check("fresh runtime per execution", () => eq(globalThis.gasbbFileEvaluations, 1));
  check("nothing left from earlier executions", () => eq([leftover, gasbb.evalString("(some? (resolve 'user/previous-run))")], [undefined, false]));
  gasbb.evalString("(def previous-run true)");
  globalThis.gasbbPreviousRun = true;
  check("no setTimeout in Apps Script", () => eq(typeof setTimeout, "undefined"));
  check("error message", () => eq(gasbb.replEval([], "(inc y)").error.message, "Unable to resolve symbol: y"));
  return { version: gasbb.version, results };
}
